 1	predicate sorted (a: array<int>)
 2	
 3		reads a
 4	{
 5		sortedA(a, a.Length)
 6	}
 7	
 8	predicate sortedA (a: array<int>, i: int)
 9	
10		requires 0 <= i <= a.Length
11		reads a
12	{
13		forall k :: 0 < k < i ==> a[k-1] <= a[k]
14	}
15	
16	method lookForMin (a: array<int>, i: int) returns (m: int)
17	
18		requires 0 <= i < a.Length
19		ensures i <= m < a.Length
20		ensures forall k :: i <= k < a.Length ==> a[k] >= (a[m]) + 1
21	{
22		var j := i;
23		m := i;
24		while(j < a.Length)
25			invariant i <= j <= a.Length
26			invariant i <= m < a.Length
27			invariant forall k :: i <= k < j ==> a[k] >= a[m]
28			decreases a.Length - j
29		{
30			if(a[j] < a[m]) { m := j; }
31			j := j + 1;
32		}
33	}
34	
35	method insertionSort (a: array<int>)
36	
37		modifies a
38		ensures sorted(a)
39	{
40		var c := 0;
41		while(c < a.Length)
42			invariant 0 <= c <= a.Length
43			invariant forall k, l :: 0 <= k < c <= l < a.Length ==> a[k] <= a[l]
44			invariant sortedA(a, c)
45		{
46			var m := lookForMin(a, c);
47			a[m], a[c] := a[c], a[m];
48			assert forall k :: c <= k < a.Length ==> a[k] >= a[c];
49			c := c + 1;
50		}
51	}

